const { test } = await import(process.env.VITEST ? 'vitest' : 'node:test');
import assert from 'node:assert/strict';
import { createHash, X509Certificate } from 'node:crypto';
import { readFileSync, writeFileSync, mkdtempSync, mkdirSync, rmSync, renameSync } from 'node:fs';
import { execFileSync, spawnSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { preapprove, verifyFetched, pinRecord, verifySignerIdentity, BOUND_PATHS, SCRUB_EXCLUDED_WORKFLOWS, IDENTITY, STRINGS } from './windows-qualsign-verify.mjs';

const hash=data=>createHash('sha256').update(data).digest('hex');
const blob=data=>createHash('sha1').update(`blob ${Buffer.byteLength(data)}\0`).update(data).digest('hex');
const b64=data=>Buffer.from(data).toString('base64');
const devSha='a'.repeat(40), publicSha='b'.repeat(40);
const oidc={use_default:true,use_immutable_subject:true,sub_claim_prefix:'repo:FerroxLabs@282419864/murage@1353175124'};
function approval() {
  const workflow='jobs:\n  sign-collector:\n    environment: windows-qualsign\n', other='jobs:\n  admitted:\n    permissions:\n      id-token: write\n';
  const workflows=Object.fromEntries([[BOUND_PATHS.workflow,workflow],['.github/workflows/release.yml',other]].map(([path,text])=>[path,{blob:blob(text),bytes:b64(text)}]));
  const objects=Object.fromEntries(Object.keys(BOUND_PATHS).map((key,n)=>[key,String(n+1).repeat(40)]));
  objects.workflow=blob(workflow);
  return {devSha,dev:{sha:devSha,objects,workflows,nugetConfigs:{}},publicCommit:{sha:publicSha,parents:['c'.repeat(40)],ref:'ci/try-012345abcdef',subject:`QUALSIGN collector ${devSha}`,objects:structuredClone(objects),workflows:structuredClone(workflows),nugetConfigs:{}},oidcSubjectCustomization:structuredClone(oidc)};
}
function addExcluded(side) {
  for(const path of SCRUB_EXCLUDED_WORKFLOWS){const text=`jobs:\n  private-${path.length}: {}\n`;side.workflows[path]={blob:blob(text),bytes:b64(text)};}
}
function setWorkflow(input,path,text,both=false) {
  input.publicCommit.workflows[path]={blob:blob(text),bytes:b64(text)};
  if(both) input.dev.workflows[path]=structuredClone(input.publicCommit.workflows[path]);
}
test('W5 preapproval binds both commits, all objects, all workflow bytes and immutable OIDC',()=>{
  const input=approval(), record=preapprove(input);
  assert.equal(record.devSha,devSha); assert.equal(record.publicSha,publicSha);
  const {recordSha256,...body}=record;
  const canonical=value=>Array.isArray(value)?value.map(canonical):value&&typeof value==='object'?Object.fromEntries(Object.keys(value).sort().map(key=>[key,canonical(value[key])])):value;
  assert.equal(recordSha256,hash(JSON.stringify(canonical(body))));
  const reordered=structuredClone(input); reordered.dev.objects=Object.fromEntries(Object.entries(reordered.dev.objects).reverse());
  assert.deepEqual(preapprove(reordered),record);
});
for(const [name,mutate] of [
  ['M-QS8 two parents',i=>i.publicCommit.parents.push('d'.repeat(40))],
  ['no parent',i=>i.publicCommit.parents=[]],
  ['M-Q17 invalid dev SHA',i=>i.devSha='invalid'],
  ['invalid public SHA',i=>i.publicCommit.sha='invalid'],
  ['wrong dev commit',i=>i.dev.sha=publicSha],
  ['wrong subject',i=>i.publicCommit.subject+=' extra'],
  ['wrong ref',i=>i.publicCommit.ref='main'],
  ['long ref',i=>i.publicCommit.ref+='0'],
  ...Object.keys(BOUND_PATHS).map(key=>[`M-QS6/M-Q15 ${key} mismatch`,i=>i.publicCommit.objects[key]='f'.repeat(40)]),
  ['missing bind object',i=>delete i.publicCommit.objects.helper],
  ['extra bind object',i=>i.publicCommit.objects.other='e'.repeat(40)],
  ['G3 changed unrelated workflow',i=>setWorkflow(i,'.github/workflows/release.yml','jobs:\n  altered: {}\n')],
  ['G3 removed workflow',i=>delete i.publicCommit.workflows['.github/workflows/release.yml']],
  ['G3 added workflow',i=>setWorkflow(i,'.github/workflows/extra.yml','jobs:\n  extra: {}\n')],
  ['forged workflow blob',i=>i.publicCommit.workflows[BOUND_PATHS.workflow].bytes=b64('changed')],
  ['G3 second environment',i=>setWorkflow(i,'.github/workflows/release.yml','jobs:\n  other:\n    environment: windows-qualsign\n',true)],
  ['G3 environment object',i=>setWorkflow(i,'.github/workflows/release.yml','jobs:\n  other:\n    environment: {name: windows-qualsign}\n',true)],
  ['G3 dynamic environment',i=>setWorkflow(i,'.github/workflows/release.yml','jobs:\n  other:\n    environment: ${{ inputs.environment }}\n',true)],
  ['duplicate YAML key',i=>setWorkflow(i,'.github/workflows/release.yml','jobs: {}\njobs: {}\n',true)],
  ['nuget one side only',i=>i.publicCommit.nugetConfigs['nuget.config']='e'.repeat(40)],
  ['nuget mismatch',i=>{i.dev.nugetConfigs['nuget.config']='e'.repeat(40);i.publicCommit.nugetConfigs['nuget.config']='f'.repeat(40);}],
  ['name-form OIDC',i=>i.oidcSubjectCustomization.sub_claim_prefix='repo:FerroxLabs/murage'],
  ['mutable OIDC',i=>i.oidcSubjectCustomization.use_immutable_subject=false],
]) test(`${name} is RED beside GREEN preapproval`,()=>{const input=approval();assert.doesNotThrow(()=>preapprove(input));mutate(input);assert.throws(()=>preapprove(input),{message:STRINGS.preapprove});});
test('nuget config equality and absence both pass',()=>{const i=approval();i.dev.nugetConfigs={'NuGet.Config':'e'.repeat(40)};i.publicCommit.nugetConfigs=structuredClone(i.dev.nugetConfigs);assert.doesNotThrow(()=>preapprove(i));});

