function scratch(run) {
  const dir=mkdtempSync(join(tmpdir(),'qualsign-test-'));
  try{return run(dir);}finally{rmSync(dir,{recursive:true,force:true});}
}
function generatedChain({subject='/CN=Ferrox Labs, LLC/O=Ferrox Labs, LLC/L=Neutral',issuerCn='Microsoft ID Verified CS AOC CA 04',issuerOrg='Microsoft Corporation',rootCn=IDENTITY.rootCn,pcaCn=IDENTITY.intermediateCn,pcaSubject=`/CN=${pcaCn}/O=Microsoft Corporation`,abovePca=false,noPca=false,ekus=IDENTITY.ekus,swap}={}) {
  return scratch(dir=>{
    const openssl=(...args)=>execFileSync('openssl',args,{cwd:dir,stdio:'pipe'});
    const key=name=>openssl('genpkey','-algorithm','EC','-pkeyopt','ec_paramgen_curve:P-256','-out',`${name}.key`);
    key('root');key('pca');key('issuer');key('leaf');key('above');
    openssl('req','-new','-x509','-key','root.key','-out','root.pem','-days','1','-set_serial','1','-subj',`/CN=${rootCn}/O=Microsoft Corporation`,'-addext','basicConstraints=critical,CA:TRUE','-addext','keyUsage=critical,keyCertSign,cRLSign');
    writeFileSync(join(dir,'ca.ext'),'basicConstraints=critical,CA:TRUE\nkeyUsage=critical,keyCertSign,cRLSign\n');
    openssl('req','-new','-key','above.key','-out','above.csr','-subj','/CN=Neutral Cross CA/O=Microsoft Corporation');
    openssl('x509','-req','-in','above.csr','-CA','root.pem','-CAkey','root.key','-set_serial','5','-out','above.pem','-days','1','-extfile','ca.ext');
    openssl('req','-new','-key','pca.key','-out','pca.csr','-subj',pcaSubject);
    openssl('x509','-req','-in','pca.csr','-CA',abovePca?'above.pem':'root.pem','-CAkey',abovePca?'above.key':'root.key','-set_serial','4','-out','pca.pem','-days','1','-extfile','ca.ext');
    openssl('req','-new','-utf8','-key','issuer.key','-out','issuer.csr','-subj',`/CN=${issuerCn}/O=${issuerOrg}`);
    openssl('x509','-req','-in','issuer.csr','-CA',noPca?'root.pem':'pca.pem','-CAkey',noPca?'root.key':'pca.key','-set_serial','2','-out','issuer.pem','-days','1','-extfile','ca.ext');
    openssl('req','-new','-key','leaf.key','-out','leaf.csr','-subj',subject);
    writeFileSync(join(dir,'leaf.ext'),`basicConstraints=critical,CA:FALSE\nkeyUsage=critical,digitalSignature\nextendedKeyUsage=${ekus.join(',')}\n`);
    openssl('x509','-req','-in','leaf.csr','-CA','issuer.pem','-CAkey','issuer.key','-set_serial','3','-out','leaf.pem','-days','1','-extfile','leaf.ext');
    if(swap) {
      // Same DN and subject key identifier at one link, different key: only a link signature check can tell it apart.
      key('fake');const skid=name=>openssl('x509','-in',`${name}.pem`,'-noout','-ext','subjectKeyIdentifier').toString().trim().split('\n').at(-1).trim();
      const same=(name,subj,ca,caKey)=>{
        writeFileSync(join(dir,'fake.ext'),`basicConstraints=critical,CA:TRUE\nkeyUsage=critical,keyCertSign,cRLSign\nsubjectKeyIdentifier=${skid(name)}\n`);
        openssl('req','-new','-utf8','-key','fake.key','-out','fake.csr','-subj',subj);
        if(ca) openssl('x509','-req','-in','fake.csr','-CA',ca,'-CAkey',caKey,'-set_serial','6','-out','fake.pem','-days','1','-extfile','fake.ext');
        else openssl('x509','-req','-in','fake.csr','-key','fake.key','-set_serial','6','-out','fake.pem','-days','1','-extfile','fake.ext');
      };
      if(swap==='leaf'){same('issuer',`/CN=${issuerCn}/O=${issuerOrg}`,'pca.pem','pca.key');openssl('x509','-req','-in','leaf.csr','-CA','fake.pem','-CAkey','fake.key','-set_serial','3','-out','leaf.pem','-days','1','-extfile','leaf.ext');}
      else if(swap==='issuer'){same('issuer',`/CN=${issuerCn}/O=${issuerOrg}`,'pca.pem','pca.key');renameSync(join(dir,'fake.pem'),join(dir,'issuer.pem'));}
      else if(swap==='pca'){same('pca',pcaSubject,'root.pem','root.key');renameSync(join(dir,'fake.pem'),join(dir,'pca.pem'));}
      else if(swap==='root'){same('root',`/CN=${rootCn}/O=Microsoft Corporation`);renameSync(join(dir,'fake.pem'),join(dir,'root.pem'));}
      else throw Error('unknown swap');
    }
    const cert=name=>new X509Certificate(readFileSync(join(dir,`${name}.pem`)));
    const leaf=cert('leaf'),issuer=cert('issuer'),pca=cert('pca'),root=cert('root'),above=cert('above');
    const certificates=noPca?[leaf.raw,issuer.raw,root.raw]:abovePca?[leaf.raw,issuer.raw,pca.raw,above.raw,root.raw]:[leaf.raw,issuer.raw,pca.raw,root.raw];
    return {leaf:leaf.raw,certificates,pcaSha256:hash(pca.raw),expected:{...IDENTITY,rootSha256:hash(root.raw)}};
  });
}
