  writeFileSync(file,JSON.stringify(approval()));assert.equal(JSON.parse(cli(['preapprove',file],0).stdout).devSha,devSha);
  const bad=approval();bad.publicCommit.subject='other';writeFileSync(file,JSON.stringify(bad));assert.equal(cli(['preapprove',file],1).stderr.trim(),STRINGS.preapprove);
  const f=fetched();writeFileSync(file,JSON.stringify(f.input));assert.equal(JSON.parse(cli(['verify',file],0).stdout).status,'verified');assert.equal(JSON.parse(cli(['pin',file],0).stdout).use,'witness-host-only');
  f.input.deletions[0].getStatus=200;writeFileSync(file,JSON.stringify(f.input));assert.deepEqual(JSON.parse(cli(['pin',file],2).stdout),{status:'delete-required'});
  f.input.artifacts[0].digest='wrong';writeFileSync(file,JSON.stringify(f.input));assert.equal(cli(['verify',file],1).stderr.trim(),STRINGS.verify);assert.deepEqual(JSON.parse(cli(['pin',file],2).stdout),{status:'delete-required'});
