test('WIN_CERTIFICATE alignment padding is accepted; nonzero and oversized tails fail',()=>{
  function apply(f,exe){f.entries[0][0].data=exe;f.entries[1][0].data=exe;f.input.jobOutputs.signed_sha256=hash(exe);f.editReceipt(r=>r.signedSha256=hash(exe));}
  const honest=fetched(),exe=image();exe.writeUInt32LE(exe.readUInt32LE(236),512);apply(honest,exe);assert.equal(verifyFetched(honest.input).status,'verified');
  for(const tail of [Buffer.from([1]),Buffer.alloc(8)]){const f=fetched();apply(f,image(Buffer.concat([publicSignature,tail])));assert.throws(()=>verifyFetched(f.input));}
});
